
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_ghds10r_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_ghds10r", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([1.157117648163332e+02, 1.120154740997313e+02, 1.069571774500822e+02, 1.001840214450772e+02, 9.139272794373450e+01, 8.047717899161576e+01, 6.774697778161027e+01, 5.412899566728304e+01, 4.105936860089678e+01, 2.929708928470683e+01, 1.566275935352099e+01, 3.563123300740618e+00, 2.238539181655592e+00, 1.842760705213721e+00, 1.353463335733627e+00, 9.736519920482000e-01, 7.657894460995386e-01, 6.533385393355603e-01, 5.763759639057588e-01, 5.069619990884126e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


